"""Lote 11 · encabezado/pie de créditos, documentación detallada y nombres en español en aplicacion_principal/.

Ejecutar desde la raíz del proyecto:   python instalar_encabezados_aplicacion_principal.py
Idempotente, sin .bak. No instala nada si algún archivo difiere de la versión esperada.
"""
import base64, hashlib, io, json, os, sys, zipfile

PRE = {
 "aplicacion_principal/__init__.py": "297a1a795520dfe2207001d165aae759c2b2216cc30462511cabdd333bd7fc28",
 "aplicacion_principal/cabecera.py": "6f19d7d0b0babffef4d4297d4433c3ae2609182e2133f6c6f4fc09f7c4f4093f",
 "aplicacion_principal/dialogos.py": "261a921ed3daa2a439e32bc1cafa5a6c9d6439ec47a9fa566a0ce017cc1f5499",
 "aplicacion_principal/entorno.py": "0bf5df00119aaeb0ddd56f6505f6b71cbeaa8bf23d811d40a7b47b11d01b4c49",
 "aplicacion_principal/estilos.css": "7da058d67a2faf993e7b21443c124e70f92b5e5a5783d4a1c1f2ba80b2ddfebb",
 "aplicacion_principal/estilos.py": "83ec68b92a068836970663bfcc5eaad790250f1d5844c63d3c901413fc857283",
 "aplicacion_principal/fragmentos.py": "6f3ab938a0db14e4ea7a6c4ee014d0a11ea018141d05421f9ee9dfb1982380a2",
 "aplicacion_principal/pagina.py": "b80ef3868dec9253e3b2381270fab7ac2279dfbef65adc20236e1e1278c21855",
 "aplicacion_principal/pantalla_carga.html": "8bd21131177e8212a1930bcef8d0c2a6564f758adf3f47cf05bccbfbb6c72094",
 "aplicacion_principal/vista_operativa.py": "ceac38c42530e6dbcdf7d206b4a2ce82563ec8008190289ce048b99c7bf1141b",
 "aplicacion_principal/vistas.py": "5f539dffd44e9c5eee3a2e153fd382eb1cf8287d803dad4bbfed8672d17c2fa8"
}
ARCHIVOS = ["aplicacion_principal/__init__.py", "aplicacion_principal/cabecera.py", "aplicacion_principal/dialogos.py", "aplicacion_principal/entorno.py", "aplicacion_principal/estilos.css", "aplicacion_principal/estilos.py", "aplicacion_principal/fragmentos.py", "aplicacion_principal/pagina.py", "aplicacion_principal/pantalla_carga.html", "aplicacion_principal/vista_operativa.py", "aplicacion_principal/vistas.py"]
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    if all(os.path.exists(f) and norm(open(f, "rb").read()) == nuevos[f] for f in ARCHIVOS):
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = []
    for f, h in PRE.items():
        if not os.path.exists(f):
            problemas.append("falta " + f)
        elif hashlib.sha256(norm(open(f, "rb").read())).hexdigest() != h:
            problemas.append(f + " difiere de la versión esperada (¿cambios sin subir?)")
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in ARCHIVOS:
        datos = nuevos[f]
        if b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    print("Listo: %d archivos actualizados." % len(ARCHIVOS))


if __name__ == "__main__":
    main()
